// INVERTER on FTM1: complementary pairs (COMP + DTEN), up-down counting (CPWMS, IO-61),
// dead time inserted by the FTM. Active level high side: high, low side: low.
constexpr uint32_t CLOCK_HZ           = 64000000U; // FTM input clock with SC.CLKS = 01
constexpr uint32_t FREQUENCY_HZ       = 20000U; // realised 20000.000 Hz
constexpr uint32_t DEADTIME_NS        = 750U; // realised 750.0 ns (rounded up)
constexpr uint32_t PRESCALER_SHIFT    = 0U; // SC.PS: divider 1
constexpr uint32_t PERIOD_TICKS       = 3200U; // 2 x MOD (up-down counting, CNTIN = 0)
constexpr uint32_t DEADTIME_DTPS      = 0U; // DEADTIME.DTPS
constexpr uint32_t DEADTIME_PRESCALER = 1U;
constexpr uint32_t DEADTIME_TICKS     = 48U; // DEADTIME.DTVAL
constexpr uint32_t CHANNEL_MASK       = 0xFCU; // FTM channels of all pairs
constexpr uint32_t ACTIVE_LOW_MASK    = 0xA8U; // POL: channels with active level low

// IO-61 alignment center (SC.CPWMS): the counter counts 0 .. COUNTER_TOP .. 0, the high side of a pair is on
// while the counter is below CnV (pulse symmetric to the counter minimum), so all high sides are off around the
// turning point COUNTER_TOP; new CnV values are loaded there (SYNC.CNTMAX).
#define NX_FTM_PWM_CENTER 1
constexpr uint32_t COUNTER_TOP        = 1600U; // MOD, turning point of the counter

// IO-61 trigger output (EXTTRIG) at pwm.INVERTER.trigger.point zero_low: match of channel 0 at counter 1600
#define NX_FTM_PWM_TRIGGER 1
#define NX_FTM_PWM_TRIGGER_CHANNEL 1
constexpr uint8_t TRIGGER_CHANNEL     = 0U; // unused channel of the instance, pin not muxed
constexpr uint32_t TRIGGER_VALUE      = 1600U; // C(n)V of TRIGGER_CHANNEL

// COMBINE bits of one pair (shifted by 8 * pair index)
constexpr uint32_t COMBINE_PAIR = FTM_COMBINE_COMP0_MASK | FTM_COMBINE_DTEN0_MASK | FTM_COMBINE_SYNCEN0_MASK;

inline FTM_Type& ftm() { return *FTM1; }

struct Pair
{
    uint16_t outputPwm;   // OutputPwm channel
    uint8_t highChannel;  // FTM channel 2k, low side is 2k + 1
    uint16_t highPin;     // Io::PinId
    uint16_t lowPin;
};

constexpr uint8_t PAIR_COUNT = 3U;

constexpr Pair const PAIRS[PAIR_COUNT] = {
    {OutputPwm::PHASE_U, 2U, Io::PHASE_U_HS, Io::PHASE_U_LS},
    {OutputPwm::PHASE_V, 4U, Io::PHASE_V_HS, Io::PHASE_V_LS},
    {OutputPwm::PHASE_W, 6U, Io::PHASE_W_HS, Io::PHASE_W_LS},
};

// clang-format off
constexpr tFtm::tFtmConfiguration const CONFIGURATION = {
    /* SC            */ FTM_SC_CLKS(1U) | FTM_SC_CPWMS_MASK | FTM_SC_PS(PRESCALER_SHIFT)
                        | (CHANNEL_MASK << FTM_SC_PWMEN0_SHIFT),
    /* MOD           */ COUNTER_TOP,
    /* CNTIN         */ 0U,
    /* MODE          */ FTM_MODE_FTMEN_MASK | FTM_MODE_WPDIS_MASK,
    /* SYNC          */ FTM_SYNC_CNTMAX_MASK,                  // CnV loading point: counter maximum
    /* OUTINIT       */ 0U,
    /* OUTMASK       */ CHANNEL_MASK,                          // all outputs inactive until the first duty
    /* COMBINE       */ (COMBINE_PAIR << 8U) | (COMBINE_PAIR << 16U) | (COMBINE_PAIR << 24U),
    /* DEADTIME      */ FTM_DEADTIME_DTPS(DEADTIME_DTPS) | FTM_DEADTIME_DTVAL(DEADTIME_TICKS),
    /* EXTTRIG       */ FTM_EXTTRIG_CH0TRIG_MASK,
    /* POL           */ ACTIVE_LOW_MASK,
    /* FILTER        */ 0U,
    /* FLTCTRL       */ 0U,
    /* QDCTRL        */ 0U,
    /* CONF          */ FTM_CONF_BDMMODE(1U),                  // debug halt: outputs forced to inactive level
    /* FLTPOL        */ 0U,
    /* SYNCONF       */ FTM_SYNCONF_SYNCMODE_MASK | FTM_SYNCONF_SWWRBUF_MASK, // enhanced sync, CnV on SWSYNC
    /* INVCTRL       */ 0U,
    /* SWOCTRL       */ 0U,
    /* PWMLOAD       */ 0U,
    /* HCR           */ 0U,
    // Board 2026-09-15: writing DEADTIME also sets PAIRnDEADTIME, but Ftm::init() writes these afterwards;
    // with 0 there was no dead time at all (scope). The used pairs therefore repeat DTPS/DTVAL here.
    /* PAIR0DEADTIME */ 0U,
    /* PAIR1DEADTIME */ FTM_PAIR1DEADTIME_DTPS(DEADTIME_DTPS) | FTM_PAIR1DEADTIME_DTVAL(DEADTIME_TICKS),
    /* PAIR2DEADTIME */ FTM_PAIR2DEADTIME_DTPS(DEADTIME_DTPS) | FTM_PAIR2DEADTIME_DTVAL(DEADTIME_TICKS),
    /* PAIR3DEADTIME */ FTM_PAIR3DEADTIME_DTPS(DEADTIME_DTPS) | FTM_PAIR3DEADTIME_DTVAL(DEADTIME_TICKS),
};
// clang-format on

// Independent re-check of the generator results (a hand edit or a generator bug stops the build).
constexpr bool pairsValid()
{
    uint32_t mask = 0U;
    for (uint8_t i = 0U; i < PAIR_COUNT; ++i)
    {
        Pair const& p = PAIRS[i];
        if (((p.highChannel % 2U) != 0U) || (p.highChannel > 6U)
            || (p.outputPwm != static_cast<uint16_t>(OutputPwm::_pwmDynamicStart + i)))
        {
            return false;
        }
        mask |= static_cast<uint32_t>(3U << p.highChannel);
    }
    return mask == CHANNEL_MASK;
}

static_assert(PAIR_COUNT == (OutputPwm::_pwmChannelMax - OutputPwm::_pwmDynamicStart), "pairs != PWM channels");
static_assert(pairsValid(), "pairs must use FTM channels 2k/2k+1 in OutputPwm order");
static_assert(PRESCALER_SHIFT <= 7U, "SC.PS is 3 bit");
static_assert(PERIOD_TICKS == 2U * COUNTER_TOP, "up-down counting: period is twice the turning point");
static_assert((COUNTER_TOP >= 100U) && (COUNTER_TOP + 1U <= 0xFFFFU), "MOD + 1 must fit 16 bit, >= 1 % resolution");
static_assert((TRIGGER_CHANNEL < 8U) && (((CHANNEL_MASK >> TRIGGER_CHANNEL) & 1U) == 0U),
              "the trigger channel must be a channel the group does not use");
static_assert(TRIGGER_VALUE == COUNTER_TOP, "zero_low of the up-down counter is its turning point");
static_assert((DEADTIME_TICKS >= 1U) && (DEADTIME_TICKS <= 63U), "DEADTIME.DTVAL is 6 bit, dead time > 0");
static_assert(((DEADTIME_DTPS == 0U) && (DEADTIME_PRESCALER == 1U)) || ((DEADTIME_DTPS == 2U) && (DEADTIME_PRESCALER == 4U))
                  || ((DEADTIME_DTPS == 3U) && (DEADTIME_PRESCALER == 16U)),
              "DEADTIME.DTPS and divider do not match");
static_assert(2U * DEADTIME_TICKS * DEADTIME_PRESCALER < (PERIOD_TICKS << PRESCALER_SHIFT),
              "dead time must be shorter than half the PWM period");
static_assert(static_cast<uint64_t>(DEADTIME_TICKS) * DEADTIME_PRESCALER * 1000000000ULL
                  >= static_cast<uint64_t>(DEADTIME_NS) * CLOCK_HZ,
              "realised dead time is shorter than configured");
static_assert(100ULL * ((static_cast<uint64_t>(FREQUENCY_HZ) * (PERIOD_TICKS << PRESCALER_SHIFT) > CLOCK_HZ)
                            ? (static_cast<uint64_t>(FREQUENCY_HZ) * (PERIOD_TICKS << PRESCALER_SHIFT) - CLOCK_HZ)
                            : (CLOCK_HZ - static_cast<uint64_t>(FREQUENCY_HZ) * (PERIOD_TICKS << PRESCALER_SHIFT)))
                  <= CLOCK_HZ,
              "realised frequency deviates more than 1 %");

